; BlwPlatformDxe (was BlwUcodeLate): a Framework DXE driver for the OpenFrame 1 (AMI Aptio 4, IA32).
;
; 1. SMBIOS: this firmware publishes no SMBIOS at all. The driver copies a prebuilt SMBIOS 2.4
;    entry point and structure table (Type 0 BIOS, Type 1 System, Type 127; generated by
;    build_ucode_driver.py) into EfiRuntimeServicesData, patches the table address and both
;    entry-point checksums, and installs it under the SMBIOS configuration-table GUID. Skipped if
;    an SMBIOS table is already installed.
; 2. Microcode: loads a newer CPU microcode update late in DXE, once memory and caches are up, on
;    the BSP and then on every AP through the Framework MP Services protocol. The firmware's own
;    reset-vector loader keeps loading its stock entry. Loading 0x217 at reset hangs this
;    firmware; Linux loading it at boot works.
; 3. LAN MAC, serial number and UUID: registers a ReadyToBoot event (PCI isn't enumerated yet at
;    dispatch). Its notify reads NVRAM variable BlwMac (GUID EC87D643, 6 bytes, stored by
;    BlwMac.efi; up to 26.11.19 it read BlwLanMac, the LAN MAC itself): the WLAN card's burned-in
;    address, or with no card the LAN MAC of-netplan generated (locally administered). The LAN
;    MAC (lan_mac: 02 then the card MAC's last five octets, or the generated one as it is) goes
;    into the RTL8111C's MAC0 registers, so any OS sees it; the stored MAC becomes the SMBIOS Type 1
;    UUID, and a card's also the serial number (smbios_id.inc). Read only: no variable is
;    written. The app build (-DAPP, run from boot.nsh) applies it at once instead and leaves no event.
; 4. Firmware vendor and boot count: ST->FirmwareVendor becomes "BirdsLikeWires" (Linux prints
;    "efi: EFI v2.0 by BirdsLikeWires"), with the system table CRC recomputed. At ReadyToBoot the
;    SMBIOS Type 11 string "BootCount: ----------" gets the MonotonicCounter variable's value
;    (read only). The SMBIOS table also has Type 3 (chassis 0x22, Embedded PC). The app build
;    replaces an existing SMBIOS table instead of skipping, so a test from boot.nsh shows the new one.
; 5. Memory: SMBIOS Type 16 (the array: system board, no ECC, 2 GB maximum) and Type 17 (one
;    soldered DDR2 device, 64 bits wide). At dispatch, mem_fill sets Type 17's size from the top
;    of RAM in the UEFI memory map, rounded up to a power of two, and its speed from the FSB
;    (MSR_FSB_FREQ): the SCH runs the DRAM at the FSB rate, 400 or 533 MT/s. Anything implausible
;    is left as unknown.
;
; Position-independent: data is reached through call/pop, so no relocations are needed.
; Assembled with `nasm -f bin`; build_ucode_driver.py wraps it in a PE32 image and an FFS
; file with a DXE dependency on the MP Services protocol.
;
; Entry: EFI_STATUS EFIAPI Entry(EFI_HANDLE ImageHandle, EFI_SYSTEM_TABLE *SystemTable)
; IA32 EFIAPI is cdecl. Does nothing unless the embedded update matches this CPU's signature
; and platform ID and is newer than what is running. The status says how far it got (the EFI
; shell's `load` prints it): EFI_SUCCESS = BSP updated and StartupAllAPs succeeded;
; UNSUPPORTED = update doesn't fit this CPU; ALREADY_STARTED = already this revision or newer;
; DEVICE_ERROR = the BSP didn't take it; NOT_FOUND = no MP Services (BSP only); anything else
; is StartupAllAPs' own status. Those are only returned if the ReadyToBoot event could not be
; created: once it exists the entry returns EFI_SUCCESS, because an error status makes the core
; unload the image and the event would then call freed memory. (The microcode stays loaded
; either way, and the SMBIOS copy lives in runtime-services memory, not the image.)

bits 32

entry:
        push    ebp
        mov     ebp, esp
        push    ebx
        push    esi
        push    edi
        call    .here
.here:  pop     edi                             ; edi = runtime address of .here
        call    smbios_install                  ; keeps ebx, esi, edi
        call    vendor_install                  ; keeps ebx, esi, edi
        lea     esi, [edi + (ucode - .here)]    ; esi = embedded microcode update

        mov     ebx, 0x80000003                 ; EFI_UNSUPPORTED: update doesn't fit this CPU
        cmp     dword [esi], 1                  ; header version 1
        jne     .out

        mov     eax, 1                          ; processor signature must match
        cpuid
        cmp     eax, [esi + 0x0c]
        jne     .out_unsup

        mov     ecx, 0x17                       ; IA32_PLATFORM_ID bits 52:50 -> flag bit
        rdmsr
        shr     edx, 18
        and     edx, 7
        mov     ecx, edx
        mov     eax, 1
        shl     eax, cl
        test    eax, [esi + 0x18]
        jz      .out_unsup

        call    .rev                            ; edx = running revision
        mov     ebx, 0x80000014                 ; EFI_ALREADY_STARTED: already this or newer
        cmp     edx, [esi + 4]
        jae     .out

        lea     eax, [esi + 0x30]               ; load on the BSP
        xor     edx, edx
        mov     ecx, 0x79
        wrmsr
        call    .rev
        mov     ebx, 0x80000007                 ; EFI_DEVICE_ERROR: BSP didn't take it
        cmp     edx, [esi + 4]
        jne     .out

        mov     eax, [ebp + 12]                 ; SystemTable
        mov     eax, [eax + 0x3c]               ; ->BootServices
        push    0                               ; local: Interface
        mov     edx, esp
        push    edx                             ; &Interface
        push    0                               ; Registration
        lea     ecx, [edi + (mp_guid - .here)]
        push    ecx                             ; &gFrameworkEfiMpServiceProtocolGuid
        call    [eax + 0xac]                    ; BS->LocateProtocol
        add     esp, 12
        pop     ecx                             ; Interface
        mov     ebx, 0x8000000E                 ; EFI_NOT_FOUND: no MP Services (BSP is updated)
        test    eax, eax
        jnz     .out
        test    ecx, ecx
        jz      .out

        push    0                               ; FailedCPUList
        push    esi                             ; ProcArguments = the update
        push    0                               ; TimeoutInMicroSecs (none)
        push    0                               ; WaitEvent = NULL (blocking)
        push    1                               ; SingleThread
        lea     eax, [edi + (ap_proc - .here)]
        push    eax                             ; Procedure
        push    ecx                             ; This
        call    [ecx + 8]                       ; MP->StartupAllAPs
        add     esp, 28
        mov     ebx, eax                        ; its status (EFI_SUCCESS when all APs ran)
        jmp     .out

.out_unsup:
        mov     ebx, 0x80000003
.out:
%ifdef APP
        push    dword [ebp + 12]                ; app build (run from boot.nsh, PCI already up):
        call    fill_count                      ; do the ReadyToBoot work now. An app is unloaded
        call    apply_mac                       ; when it returns, so it must not leave an event.
        add     esp, 4
%else
        call    rtb_register                    ; eax = 0 if the ReadyToBoot event was created
        test    eax, eax
        jnz     .ret
        xor     ebx, ebx                        ; EFI_SUCCESS: the image must stay resident for it
%endif
.ret:   mov     eax, ebx
        pop     edi
        pop     esi
        pop     ebx
        pop     ebp
        ret

; edx = running microcode revision (clear MSR 0x8B, CPUID(1), read MSR 0x8B). Clobbers eax, ecx.
.rev:   push    ebx
        xor     eax, eax
        xor     edx, edx
        mov     ecx, 0x8b
        wrmsr
        mov     eax, 1
        cpuid
        mov     ecx, 0x8b
        rdmsr
        pop     ebx
        ret

; VOID EFIAPI ApProc(VOID *Buffer): Buffer is the update header
ap_proc:
        mov     eax, [esp + 4]
        add     eax, 0x30
        xor     edx, edx
        mov     ecx, 0x79
        wrmsr
        ret

        align   16, db 0
mp_guid:                                        ; F33261E7-23CB-11D5-BD5C-0080C73C8881
        dd      0xf33261e7
        dw      0x23cb, 0x11d5
        db      0xbd, 0x5c, 0x00, 0x80, 0xc7, 0x3c, 0x88, 0x81

; smbios_install: in edi = entry.here, [ebp+12] = SystemTable. Keeps ebx, esi, edi, ebp.
smbios_install:
        push    ebx
        push    esi
        push    edi
        mov     ebx, edi                        ; PIC base
        mov     eax, [ebp + 12]
        mov     ecx, [eax + 0x40]               ; ST->NumberOfTableEntries
        mov     edx, [eax + 0x44]               ; ST->ConfigurationTable (GUID + pointer, 20 bytes)
.scan:  test    ecx, ecx
        jz      .alloc
        push    ecx
        lea     esi, [ebx + (smbios_guid - entry.here)]
        mov     edi, edx
        mov     ecx, 4
        repe cmpsd
        pop     ecx
%ifndef APP
        je      .done                           ; SMBIOS already present: leave it alone
%else
        je      .alloc                          ; app test: replace the firmware's table (same GUID)
%endif
        add     edx, 20
        dec     ecx
        jmp     .scan

.alloc: mov     eax, [ebp + 12]
        mov     eax, [eax + 0x3c]               ; BootServices
        push    0                               ; local: Buffer
        mov     edx, esp
        push    edx                             ; &Buffer
        push    16 + 32 + SMBIOS_LEN            ; room to align to 16
        push    6                               ; EfiRuntimeServicesData: survives into the OS
        call    [eax + 0x2c]                    ; BS->AllocatePool
        add     esp, 12
        pop     edx                             ; Buffer
        test    eax, eax
        jnz     .done
        add     edx, 15
        and     edx, 0xfffffff0                 ; edx = entry point, 16-byte aligned

        mov     edi, edx                        ; copy entry point (32) + structure table
        lea     esi, [ebx + (smbios_eps - entry.here)]
        mov     ecx, 32 + SMBIOS_LEN
        rep movsb
        lea     eax, [edx + 32]
        mov     [edx + 0x18], eax               ; structure table address
        mov     [ebx + (eps_ptr - entry.here)], edx     ; where apply_mac fills the serial and UUID
        lea     eax, [edx + 32 + SMBIOS_COUNT_OFF]
        mov     [ebx + (count_ptr - entry.here)], eax   ; where fill_count writes the boot count
        push    edx
        lea     edi, [edx + 32]
        call    mem_fill                        ; Type 17 size and speed
        pop     edx

        xor     eax, eax                        ; intermediate checksum over 0x10..0x1E
        lea     esi, [edx + 0x10]
        mov     ecx, 15
.c1:    add     al, [esi]
        inc     esi
        loop    .c1
        neg     al
        mov     [edx + 0x15], al
        xor     eax, eax                        ; entry-point checksum over 0x00..0x1E
        mov     esi, edx
        mov     ecx, 0x1f
.c2:    add     al, [esi]
        inc     esi
        loop    .c2
        neg     al
        mov     [edx + 4], al

        mov     eax, [ebp + 12]
        mov     eax, [eax + 0x3c]
        push    edx                             ; Table
        lea     ecx, [ebx + (smbios_guid - entry.here)]
        push    ecx                             ; &gEfiSmbiosTableGuid
        call    [eax + 0x6c]                    ; BS->InstallConfigurationTable
        add     esp, 8
.done:  pop     edi
        pop     esi
        pop     ebx
        ret

; ---------------------------------------------------------------------------------------------
; 5. Memory.

; mem_fill: edi = our structure table, [ebp+12] = SystemTable (entry's frame). Writes Type 17's
; size (MB, or 0xFFFF unknown) and speed (MT/s, or 0 unknown). Keeps ebx, esi, edi, ebp.
mem_fill:
        call    mem_speed                       ; eax = 400, 533 or 0
        mov     [edi + SMBIOS_MEMSPEED_OFF], ax
        push    dword [ebp + 12]
        call    mem_top                         ; eax = top of RAM, or 0
        add     esp, 4
        call    mem_round                       ; eax = MB, or 0xFFFF
        mov     [edi + SMBIOS_MEMSIZE_OFF], ax
        ret

; mem_speed: eax = the DRAM data rate in MT/s from MSR_FSB_FREQ (0xCD) bits 2:0, which on the
; Atom Z5xx (family 6 model 0x1C, the only CPU read) give the bus clock: 101b 100 MHz (400 MT/s),
; 001b 133 MHz (533 MT/s). The SCH runs DDR2 at the FSB rate (datasheet 319537 §7.2.8.1).
; Anything else: 0 (unknown). Keeps ebx, esi, edi; clobbers ecx, edx.
mem_speed:
        push    ebx
        mov     eax, 1
        cpuid
        pop     ebx
        and     eax, 0x0fff0ff0                 ; family/model, not stepping
        cmp     eax, 0x000106c0
        jne     .unk                            ; another CPU: don't touch an MSR it may not have
        mov     ecx, 0xcd
        rdmsr
        and     eax, 7
        cmp     eax, 1
        je      .s533
        cmp     eax, 5
        je      .s400
.unk:   xor     eax, eax
        ret
.s533:  mov     eax, 533
        ret
.s400:  mov     eax, 400
        ret

; mem_round: eax = top of RAM. eax = the DRAM size in MB: the next power of two at or above it,
; which must be 256 MB to 2 GB (the SCH's ranks are 256 MB to 1 GB, one or two of them, at most
; 2 GB). A top at or below 128 MB, or above 2 GB, gives 0xFFFF (unknown). Clobbers ecx.
mem_round:
        cmp     eax, 0x08000000
        jbe     .unk
        mov     ecx, 0x10000000
.up:    cmp     ecx, eax
        jae     .ok
        shl     ecx, 1
        jnc     .up                             ; past 2 GB the bit falls out
.unk:   mov     eax, 0xffff
        ret
.ok:    mov     eax, ecx
        shr     eax, 20
        ret

; UINT32 mem_top(EFI_SYSTEM_TABLE *St): the end of the highest RAM region below 4 GB in the UEFI
; memory map (loader, boot and runtime services, conventional, ACPI reclaim and NVS), or 0.
; Reserved, unusable and MMIO regions don't count: this firmware marks everything from the
; graphics stolen memory up to 2 GB reserved. cdecl; keeps ebx, esi, edi.
mem_top:
        push    ebp
        mov     ebp, esp
        sub     esp, 24                         ; -4 MapSize, -8 MapKey, -12 DescSize, -16 DescVer,
        push    ebx                             ; -20 Buffer, -24 the result
        push    esi
        push    edi
        xor     eax, eax
        mov     [ebp - 4], eax
        mov     [ebp - 12], eax
        mov     [ebp - 20], eax
        mov     [ebp - 24], eax
        call    .getmap                         ; size 0: asks how big the map is
        cmp     eax, 0x80000005                 ; EFI_BUFFER_TOO_SMALL
        jne     .out
        mov     eax, [ebp - 12]
        cmp     eax, 40                         ; a descriptor must reach NumberOfPages
        jb      .out
        cmp     eax, 256
        ja      .out
        shl     eax, 2                          ; room for the allocation's own entries
        add     [ebp - 4], eax
        mov     eax, [ebp + 8]
        mov     eax, [eax + 0x3c]               ; BootServices
        lea     ecx, [ebp - 20]
        push    ecx                             ; &Buffer
        push    dword [ebp - 4]                 ; Size
        push    4                               ; EfiBootServicesData
        call    [eax + 0x2c]                    ; AllocatePool
        add     esp, 12
        test    eax, eax
        jnz     .out
        call    .getmap
        test    eax, eax
        jnz     .free
        mov     esi, [ebp - 20]
        mov     ecx, [ebp - 4]                  ; bytes of map
        mov     edx, [ebp - 12]                 ; descriptor size
        cmp     edx, 40
        jb      .free
.desc:  cmp     ecx, edx
        jb      .free
        mov     eax, [esi]                      ; Type
        test    eax, eax
        jz      .next                           ; EfiReservedMemoryType
        cmp     eax, 8
        je      .next                           ; EfiUnusableMemory
        cmp     eax, 10
        ja      .next                           ; MMIO, MMIO port space, PAL code
        cmp     dword [esi + 12], 0             ; PhysicalStart above 4 GB
        jne     .next
        cmp     dword [esi + 28], 0             ; NumberOfPages, high half
        jne     .next
        mov     eax, [esi + 24]                 ; NumberOfPages
        cmp     eax, 0x100000
        jae     .next                           ; 4 GB or more
        shl     eax, 12
        add     eax, [esi + 8]                  ; end = PhysicalStart + pages * 4 KB
        jc      .next
        cmp     eax, [ebp - 24]
        jbe     .next
        mov     [ebp - 24], eax
.next:  add     esi, edx
        sub     ecx, edx
        jmp     .desc
.free:  mov     eax, [ebp + 8]
        mov     eax, [eax + 0x3c]
        push    dword [ebp - 20]
        call    [eax + 0x30]                    ; FreePool
        add     esp, 4
.out:   mov     eax, [ebp - 24]
        pop     edi
        pop     esi
        pop     ebx
        mov     esp, ebp
        pop     ebp
        ret

; GetMemoryMap(&MapSize, Buffer, &MapKey, &DescSize, &DescVer), in mem_top's frame. eax = status.
.getmap:
        lea     eax, [ebp - 16]
        push    eax                             ; &DescriptorVersion
        lea     eax, [ebp - 12]
        push    eax                             ; &DescriptorSize
        lea     eax, [ebp - 8]
        push    eax                             ; &MapKey
        push    dword [ebp - 20]                ; MemoryMap
        lea     eax, [ebp - 4]
        push    eax                             ; &MemoryMapSize
        mov     eax, [ebp + 8]
        mov     eax, [eax + 0x3c]
        call    [eax + 0x28]                    ; GetMemoryMap
        add     esp, 20
        ret

; ---------------------------------------------------------------------------------------------
; 3. LAN MAC. The RTL8111C has no stored address. BlwMac.efi (run from boot.nsh) keeps one in
;    NVRAM variable BlwMac; this writes it into MAC0 at ReadyToBoot, so every OS sees it.
;    It only reads NVRAM: there is no SetVariable anywhere in this driver.

F_NIC_MISSING   equ 0x1000                      ; no 10ec:8168 behind 00:1c.0, or no I/O BAR
F_NIC_DONE      equ 0x2000                      ; MAC0 written and read back correctly
F_NIC_VERIFY    equ 0x4000                      ; MAC0 read back wrong

; rtb_register: in edi = entry.here, [ebp+12] = SystemTable. CreateEventEx(EVT_NOTIFY_SIGNAL,
; TPL_CALLBACK, rtb_notify, SystemTable, &gEfiEventReadyToBootGuid). eax = its status, or
; EFI_UNSUPPORTED if boot services are older than UEFI 2.0 (no CreateEventEx). Keeps ebx, esi, edi.
rtb_register:
        mov     eax, [ebp + 12]
        mov     eax, [eax + 0x3c]               ; BootServices
        cmp     dword [eax + 0x0c], 0xc8        ; HeaderSize must cover CreateEventEx (+0xC4)
        jb      .old
        push    0                               ; local: Event (kept for the whole boot)
        mov     edx, esp
        push    edx                             ; &Event
        lea     ecx, [edi + (rtb_guid - entry.here)]
        push    ecx                             ; EventGroup
        push    dword [ebp + 12]                ; NotifyContext = SystemTable
        lea     ecx, [edi + (rtb_notify - entry.here)]
        push    ecx                             ; NotifyFunction
        push    8                               ; TPL_CALLBACK
        push    0x200                           ; EVT_NOTIFY_SIGNAL
        call    [eax + 0xc4]                    ; BS->CreateEventEx
        add     esp, 28
        ret
.old:   mov     eax, 0x80000003
        ret

; VOID EFIAPI rtb_notify(EFI_EVENT Event, VOID *Context = SystemTable): the ReadyToBoot work
rtb_notify:
        push    dword [esp + 8]
        call    fill_count
        call    apply_mac
        add     esp, 4
        ret

; ---------------------------------------------------------------------------------------------
; 4. Boot count and firmware vendor.

; VOID fill_count(EFI_SYSTEM_TABLE *St): if this driver installed the SMBIOS table, write the
; MonotonicCounter variable (EFI global GUID, 4 bytes: the firmware bumps it once per boot, early
; in DXE) as 10 decimal digits over the Type 11 placeholder. Read only. cdecl.
fill_count:
        push    ebp
        mov     ebp, esp
        sub     esp, 16                         ; -8 data[8], -12 DataSize, -16 Attributes
        push    ebx
        push    esi
        push    edi
        call    .here
.here:  pop     ebx
        mov     edi, [ebx + (count_ptr - .here)]
        test    edi, edi
        jz      .out                            ; not our table: leave it alone
        mov     dword [ebp - 12], 8
        lea     eax, [ebp - 8]
        push    eax                             ; Data
        lea     eax, [ebp - 12]
        push    eax                             ; &DataSize
        lea     eax, [ebp - 16]
        push    eax                             ; &Attributes
        lea     eax, [ebx + (global_guid - .here)]
        push    eax
        lea     eax, [ebx + (name_mtc - .here)]
        push    eax
        mov     eax, [ebp + 8]
        mov     eax, [eax + 0x38]               ; RuntimeServices
        call    [eax + 0x30]                    ; RT->GetVariable
        add     esp, 20
        test    eax, eax
        jnz     .out                            ; placeholder stays
        cmp     dword [ebp - 12], 4
        jne     .out
        mov     eax, [ebp - 8]
        mov     ecx, 10
        mov     esi, 10
.dig:   xor     edx, edx                        ; last digit first
        div     esi
        add     dl, '0'
        mov     [edi + ecx - 1], dl
        dec     ecx
        jnz     .dig
.out:   pop     edi
        pop     esi
        pop     ebx
        mov     esp, ebp
        pop     ebp
        ret

; vendor_install: in edi = entry.here, [ebp+12] = SystemTable. Points ST->FirmwareVendor at a copy
; of "BirdsLikeWires" in EfiRuntimeServicesData (the kernel reads it after ExitBootServices) and
; recomputes the system table's CRC32. If that fails, the old pointer and CRC are put back.
; Keeps ebx, esi, edi.
vendor_install:
        push    ebx
        push    esi
        push    edi
        mov     ebx, edi                        ; PIC base
        mov     eax, [ebp + 12]
        mov     eax, [eax + 0x3c]               ; BootServices
        push    0                               ; local: Buffer
        mov     edx, esp
        push    edx                             ; &Buffer
        push    VENDOR_BYTES
        push    6                               ; EfiRuntimeServicesData
        call    [eax + 0x2c]                    ; BS->AllocatePool
        add     esp, 12
        pop     edx                             ; Buffer
        test    eax, eax
        jnz     .done
        mov     edi, edx
        lea     esi, [ebx + (fw_vendor - entry.here)]
        mov     ecx, VENDOR_BYTES
        rep movsb
        mov     ecx, [ebp + 12]                 ; ST
        push    dword [ecx + 0x18]              ; old FirmwareVendor
        push    dword [ecx + 0x10]              ; old Hdr.CRC32
        mov     [ecx + 0x18], edx
        mov     dword [ecx + 0x10], 0           ; the CRC is computed with its own field zero
        push    0                               ; local: Crc32
        mov     eax, esp
        push    eax                             ; &Crc32
        push    dword [ecx + 0x0c]              ; Hdr.HeaderSize
        push    ecx                             ; Data = ST
        mov     eax, [ecx + 0x3c]
        call    [eax + 0xb8]                    ; BS->CalculateCrc32
        add     esp, 12
        pop     edx                             ; Crc32
        mov     ecx, [ebp + 12]
        test    eax, eax
        jnz     .undo
        mov     [ecx + 0x10], edx
        add     esp, 8
        jmp     .done
.undo:  pop     dword [ecx + 0x10]              ; old CRC
        pop     dword [ecx + 0x18]              ; old FirmwareVendor
.done:  pop     edi
        pop     esi
        pop     ebx
        ret

; UINT32 apply_mac(EFI_SYSTEM_TABLE *St): GetVariable(BlwMac), which must be 6 bytes, unicast and
; not all zero. If this driver installed the SMBIOS table, fill in Type 1's UUID (and for a card's
; MAC the serial number) from it; then write the LAN MAC made from it into MAC0.
; Returns 0 (MAC0 not written) or an F_NIC_* flag. cdecl.
apply_mac:
        push    ebp
        mov     ebp, esp
        sub     esp, 32                         ; -16 data[16], -20 DataSize, -24 Attributes, -32 lan[8]
        push    ebx
        push    esi
        push    edi
        cld
        call    .here
.here:  pop     ebx
        mov     dword [ebp - 20], 16
        lea     eax, [ebp - 16]
        push    eax                             ; Data
        lea     eax, [ebp - 20]
        push    eax                             ; &DataSize
        lea     eax, [ebp - 24]
        push    eax                             ; &Attributes
        lea     eax, [ebx + (blw_guid - .here)]
        push    eax
        lea     eax, [ebx + (name_blwmac - .here)]
        push    eax
        mov     eax, [ebp + 8]
        mov     eax, [eax + 0x38]               ; RuntimeServices
        call    [eax + 0x30]                    ; RT->GetVariable
        add     esp, 20
        xor     edi, edi                        ; edi = what to return
        test    eax, eax
        jnz     .out                            ; not stored (or bigger than 16 bytes)
        cmp     dword [ebp - 20], 6
        jne     .out
        lea     esi, [ebp - 16]
        call    mac_ok
        test    eax, eax
        jz      .out
        mov     esi, [ebx + (eps_ptr - .here)]
        test    esi, esi
        jz      .lan                            ; not our table: leave it alone
        lea     edx, [ebp - 16]
        call    smbios_set_id
.lan:   lea     esi, [ebp - 16]
        lea     edi, [ebp - 32]
        call    lan_mac
        lea     esi, [ebp - 32]
        call    program_nic                     ; eax = F_NIC_*
        mov     edi, eax
.out:   mov     eax, edi
        pop     edi
        pop     esi
        pop     ebx
        mov     esp, ebp
        pop     ebp
        ret

; mac_ok: esi = 6 bytes. eax = 1 if unicast and not all zero. Keeps esi; clobbers ecx, edx.
mac_ok: xor     eax, eax
        test    byte [esi], 1                   ; multicast bit
        jnz     .r
        mov     ecx, [esi]
        movzx   edx, word [esi + 4]
        or      ecx, edx
        jz      .r
        mov     eax, 1
.r:     ret

